@startuml

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Member {
}

class Center {
  + Name : string
  + Address : string
}

class Room {
  + RoomNumber : int
  + MaxCapacity : int
}

class Session {
  + Date : date
  + StartHour : time
}

class GroupSession {
  + Type : string
}

class IndividualSession {}

class Participation {
}

Trainer --|> Person
Member --|> Person

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session

Session --|> GroupSession
Session --|> IndividualSession

GroupSession "1" -- "1" Trainer : supervisedBy
Trainer "1" -- "0..*" GroupSession : supervises

Person "1" -- "0..*" Participation
Session "1" -- "0..*" Participation
Participation "1" -- "1" Person : participant

Member "0..*" -- "0..*" Session : participatesIn
Trainer "0..*" -- "0..*" Session : supervises
@enduml

